import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Dépannage","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/troubleshooting.md","filePath":"fr/guide/troubleshooting.md","lastUpdated":1793173149000}`),a={name:`fr/guide/troubleshooting.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to “Dépannage”">​</a></h1><p>Cette page rassemble les problèmes courants et la manière de les résoudre.</p><h2 id="l-application-ne-demarre-pas-ou-plante-au-lancement" tabindex="-1">L&#39;application ne démarre pas ou plante au lancement <a class="header-anchor" href="#l-application-ne-demarre-pas-ou-plante-au-lancement" aria-label="Permalink to “L&#39;application ne démarre pas ou plante au lancement”">​</a></h2><p>Symptômes : Sudoku ne s&#39;ouvre pas, plante immédiatement ou affiche une erreur inattendue.</p><p>Étapes à essayer :</p><ol><li>Vérifiez que votre appareil répond à la configuration minimale (iOS/iPadOS 16+, macOS 15+).</li><li>Forcez la fermeture de l&#39;application, puis relancez-la.</li><li>Redémarrez votre appareil.</li><li>Réinstallez l&#39;application depuis l&#39;App Store.</li><li>Si le problème persiste, ouvrez une issue sur le dépôt du projet en fournissant les détails.</li></ol><h2 id="problemes-de-performance" tabindex="-1">Problèmes de performance <a class="header-anchor" href="#problemes-de-performance" aria-label="Permalink to “Problèmes de performance”">​</a></h2><p>Si le jeu saccade ou ralentit :</p><ol><li>Fermez les autres applications gourmandes en ressources.</li><li>Sur Mac, consultez le Moniteur d&#39;activité pour repérer une utilisation élevée du processeur.</li><li>Sur les appareils plus anciens, essayez un niveau de difficulté plus simple (Facile ou Moyen).</li></ol><h2 id="la-synchronisation-icloud-ne-fonctionne-pas" tabindex="-1">La synchronisation iCloud ne fonctionne pas <a class="header-anchor" href="#la-synchronisation-icloud-ne-fonctionne-pas" aria-label="Permalink to “La synchronisation iCloud ne fonctionne pas”">​</a></h2><p>Si votre progression ne se synchronise pas entre vos appareils :</p><ol><li>Vérifiez que vous êtes connecté au même identifiant Apple sur tous les appareils.</li><li>Vérifiez que iCloud Drive est activé dans Réglages Système (Mac) ou Réglages (iOS/iPadOS).</li><li>Assurez-vous de disposer d&#39;une connexion internet active.</li><li>Désactivez puis réactivez iCloud pour Sudoku dans Réglages → [Votre nom] → iCloud → Apps utilisant iCloud.</li><li>Redémarrez tous les appareils, puis réessayez.</li></ol><h2 id="game-center-ne-se-connecte-pas" tabindex="-1">Game Center ne se connecte pas <a class="header-anchor" href="#game-center-ne-se-connecte-pas" aria-label="Permalink to “Game Center ne se connecte pas”">​</a></h2><p>Si les succès ou les classements Game Center ne se mettent pas à jour :</p><ol><li>Vérifiez que vous êtes connecté à Game Center (Réglages → Game Center sur iOS ; Réglages Système sur Mac).</li><li>Vérifiez votre connexion internet.</li><li>Déconnectez-vous de Game Center, puis reconnectez-vous.</li></ol><h2 id="consulter-les-journaux" tabindex="-1">Consulter les journaux <a class="header-anchor" href="#consulter-les-journaux" aria-label="Permalink to “Consulter les journaux”">​</a></h2><p>Pour diagnostiquer les plantages, les journaux de l&#39;application sont utiles. Dans les versions sandbox (App Store) sur Mac, consultez :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/Library/Containers/com.w3cub.sudoku/Data/Library/Logs/sudoku/sudoku.log</span></span></code></pre></div><p>Sur iOS/iPadOS, connectez votre appareil à un Mac et utilisez Console.app pour consulter les journaux en filtrant sur « Sudoku ».</p><h2 id="reinitialiser-l-application" tabindex="-1">Réinitialiser l&#39;application <a class="header-anchor" href="#reinitialiser-l-application" aria-label="Permalink to “Réinitialiser l&#39;application”">​</a></h2><p>Pour réinitialiser les réglages et effacer les données locales (Mac) :</p><ol><li>Quittez Sudoku</li><li>Supprimez le conteneur (attention : cela efface tous les réglages, les statistiques et les parties sauvegardées) :</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><ol start="3"><li>Rouvrez Sudoku et reconfigurez l&#39;application.</li></ol><p>Sur iPhone/iPad, supprimez puis réinstallez l&#39;application pour réinitialiser toutes les données.</p><p><strong>Remarque</strong> : si vous utilisez la synchronisation iCloud, une réinitialisation sur un appareil peut entraîner un nouveau téléchargement des données depuis iCloud après le redémarrage. Pour une réinitialisation complète sur tous les appareils, vous devrez peut-être la faire sur chacun d&#39;eux.</p><h2 id="signaler-un-probleme" tabindex="-1">Signaler un problème <a class="header-anchor" href="#signaler-un-probleme" aria-label="Permalink to “Signaler un problème”">​</a></h2><p>Lorsque vous ouvrez une issue, indiquez :</p><ul><li>Le type d&#39;appareil (iPhone, iPad ou Mac)</li><li>La version du système (Réglages → Général → Informations)</li><li>La version de Sudoku (Réglages → À propos)</li><li>Les étapes pour reproduire le problème</li><li>Les journaux ou captures d&#39;écran si vous en avez</li></ul><p>Cela aide les mainteneurs à identifier et à corriger le problème plus rapidement.</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};